<?php
namespace App\Modules\CRM\Domain\Entities;
use DateTimeImmutable;
final class Contact
{
 public const LIFECYCLE=['CONTACT','PROSPECT','CUSTOMER'];
 public const SALES_STAGES=['NEW','CONTACTED','INTERESTED','NEGOTIATION','CLOSED','REPURCHASE','LOST'];
 public function __construct(private string $id,private string $partnerId,private string $whatsapp,private string $name,private ?int $age,private ?string $gender,private ?float $heightCm,private ?string $profile,private string $lifecycleStage,private string $salesStage,private array $contactSource,private ?string $assignedAdvisorId=null,private ?string $lossReason=null,private array $metricsSummary=[],private int $totalMeasurements=0,private ?DateTimeImmutable $lastMeasurementAt=null,private DateTimeImmutable $createdAt=new DateTimeImmutable(),private ?DateTimeImmutable $updatedAt=null,private ?DateTimeImmutable $deletedAt=null){$this->assertStages();}
 public function getId():string{return $this->id;} public function getPartnerId():string{return $this->partnerId;} public function getWhatsapp():string{return $this->whatsapp;} public function getName():string{return $this->name;} public function getAge():?int{return $this->age;} public function getGender():?string{return $this->gender;} public function getHeightCm():?float{return $this->heightCm;} public function getProfile():?string{return $this->profile;} public function getLifecycleStage():string{return $this->lifecycleStage;} public function getSalesStage():string{return $this->salesStage;} public function getAssignedAdvisorId():?string{return $this->assignedAdvisorId;} public function getContactSource():array{return $this->contactSource;} public function getLossReason():?string{return $this->lossReason;} public function getMetricsSummary():array{return $this->metricsSummary;} public function getTotalMeasurements():int{return $this->totalMeasurements;} public function getLastMeasurementAt():?DateTimeImmutable{return $this->lastMeasurementAt;} public function getCreatedAt():DateTimeImmutable{return $this->createdAt;} public function getUpdatedAt():?DateTimeImmutable{return $this->updatedAt;} public function getDeletedAt():?DateTimeImmutable{return $this->deletedAt;}
 public function assignToAdvisor(string $advisorId):void{$this->assignedAdvisorId=$advisorId;if($this->lifecycleStage==='CONTACT')$this->lifecycleStage='PROSPECT';$this->updatedAt=new DateTimeImmutable();}
 public function changeSalesStage(string $newStage,?string $lossReason=null):void{if(!in_array($newStage,self::SALES_STAGES,true))throw new \InvalidArgumentException('Etapa comercial inválida.');$this->salesStage=$newStage;$this->lossReason=$newStage==='LOST'?$lossReason:null;$this->updatedAt=new DateTimeImmutable();}
 public function promoteToCustomer():void{$this->lifecycleStage='CUSTOMER';$this->salesStage='CLOSED';$this->updatedAt=new DateTimeImmutable();}
 private function assertStages():void{if(!in_array($this->lifecycleStage,self::LIFECYCLE,true)||!in_array($this->salesStage,self::SALES_STAGES,true))throw new \InvalidArgumentException('Estado de contacto inválido.');}
}
